export function drawAerialFallback(ctx,race,width,height){const atlasWidth=Math.min(1600,Math.ceil(width*1.5)),atlasHeight=Math.round(atlasWidth*height/width),key=[race.circuit,race.difficulty,race.trackLength,race.settings.roadHalf,atlasWidth,atlasHeight].join(':');let atlas=atlasCache.get(key);if(!atlas){atlas=buildAerialAtlas(race,atlasWidth,atlasHeight);atlasCache.set(key,atlas);if(atlasCache.size>3)atlasCache.delete(atlasCache.keys().next().value);}ctx.drawImage(atlas.canvas,0,0,width,height);const ratio=width/atlasWidth;return point=>atlas.project(point).map(value=>value*ratio);}
